import functools


def shout(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs).upper()

    wrapper.calls = 0
    return wrapper


@shout
def greet(name, punctuation="!"):
    return f"hello, {name}{punctuation}"


print(greet("ana"))
print(greet("ben", punctuation="?"))
print(greet.__name__, greet.calls)

