import functools


def prefix(text):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return f"{text} {func(*args, **kwargs)}"

        return wrapper

    return decorator


@prefix("A:")
@prefix("B:")
def status(name):
    return f"{name} is up"


@prefix("Note:")
def tip():
    return "save often"


print(status("db"))
print(tip())
print(status.__name__)
